'use strict';
const Module = require('module');
const fs = require('fs');
const { isDeepStrictEqual: equal } = require('util');
const original_load = Module._load;
let recorded = 0;
Module._load = function(request, parent, ...args) {
	const value = original_load.call(this, request, parent, ...args);
	if (request !== './btp_sync_locks/resources' || !parent?.filename.startsWith('/tmp/bts-queue-responsiveness-') ||
		!parent.filename.endsWith('/server-0/bts/btp_sync_plan.js')) return value;
	const ordering = parent.require('./btp_sync_locks/ordering_only');
	return function(key, before, changes, effects) {
		const scope = value(key, before, changes, effects);
		if (scope.diagnostics.allocation_scope === 'ordering_only' || recorded++ >= 64) return scope;
		const ids = new Set(changes.map(change => change.id));
		const docs = new Map(before.matches.map(match => [match._id, match]));
		const non_ordering = changes.filter(change => !ordering([change], []));
		const excluded = effects.filter(effect => !ordering(changes, [effect]));
		const row = { ts: Date.now(), scope: scope.diagnostics, changes: changes.length, effects: effects.length,
			non_ordering_changes: non_ordering.slice(0, 6).map(change => ({ id: change.id, collection: change.collection,
				set: Object.keys(change.update?.$set || {}), unset: Object.keys(change.update?.$unset || {}) })),
			non_ordering_count: non_ordering.length,
			excluded_effects: excluded.slice(0, 6).map(effect => { const note = effect.resources.notification;
				const id = note?.value?.match__id || note?.value?._id;
				return { resources: Object.keys(effect.resources), type: note?.ctype, id,
					direct_change: ids.has(id), known_match: docs.has(id),
					unchanged_full_payload: equal(docs.get(id), note?.value?.match), payload_fields: Object.keys(note?.value || {}) };
			}), excluded_count: excluded.length };
		fs.appendFileSync('/tmp/bts-plan-rejections-diagnostic.jsonl', JSON.stringify(row) + '\n');
		return scope;
	};
};
